def fee_label(p):
    if p.get('packageAmount') and p.get('additionalPerPerson'):
        return f"₹{p['packageAmount']:,} for up to {p.get('packageCovers') or '-'} people, +₹{p['additionalPerPerson']:,} per extra person"
    if p.get('packageAmount'):
        return f"₹{p['packageAmount']:,} per ticket (up to {p.get('packageCovers') or '-'} people)"
    if p.get('perPersonIndian'):
        return f"₹{p['perPersonIndian']:,} per person (Indian), ₹{p.get('perPersonForeign', 0):,} (foreign)"
    if p.get('perPerson'):
        return f"₹{p['perPerson']:,} per person"
    if p.get('entryFees'):
        e = p['entryFees']
        first = next(iter(e.items()))
        return f"From ₹{first[1]} ({first[0]})"
    return 'Price on request'


